"use client";
import Link from "next/link";
import { useMemo, useState } from "react";
import { courses, rankCourses } from "@/lib/data";
import { useApp } from "./app-provider";
import { Icon } from "./icon";
import { CourseCard, SaveCourse } from "./course-card";

export function CoursesPage() {
  const {profile,saved}=useApp();
  const [query,setQuery]=useState("");const [format,setFormat]=useState("All formats");const [level,setLevel]=useState("All levels");const [onlySaved,setOnlySaved]=useState(false);const [showMethod,setShowMethod]=useState(false);
  const filtered=useMemo(()=>courses.filter(c=>`${c.id} ${c.title} ${c.tags.join(" ")}`.toLowerCase().includes(query.trim().toLowerCase())&&(format==="All formats"||c.format===format)&&(level==="All levels"||c.level===level)&&(!onlySaved||saved.includes(c.id))),[query,format,level,onlySaved,saved]);
  const ranked=rankCourses(profile).filter(r=>filtered.some(c=>c.id===r.course.id));
  const top=ranked.slice(0,3);const topIds=top.map(r=>r.course.id);
  const rest=filtered.filter(c=>!topIds.includes(c.id)).sort((a,b)=>a.title.localeCompare(b.title));
  const isFiltering=query.trim()||format!=="All formats"||level!=="All levels"||onlySaved;
  return <div className="page courses-page">
    <section className="page-heading"><div><div className="eyebrow"><span/>A LITTLE CURIOSITY. A LOT OF POSSIBILITY.</div><h1>Find your next <em>favorite class.</em></h1><p>Courses that connect what you love with where you want to go.</p></div><Link href="/profile" className="btn secondary"><Icon name="sliders" size={16}/>My preferences</Link></section>
    <section className="discovery-banner"><div className="banner-content"><span className="light-eyebrow"><Icon name="spark" size={15}/> YOUR INTERESTS, CONNECTED.</span><h2>A class today.<br/>A new direction tomorrow.</h2><p>Explore courses, meet new ideas, and discover<br className="desktop-break"/> the research they could lead you to.</p><Link href="/chat" className="btn cream">Find my direction <Icon name="arrow" size={16}/></Link></div><div className="orbit-art" aria-hidden="true"><div className="orbit orbit-one"/><div className="orbit orbit-two"/><div className="orbit orbit-three"/><div className="orbit-center"><Icon name="compass" size={78}/></div><div className="orbit-label label-one"><Icon name="book" size={18}/><span>Your next course</span></div><div className="orbit-label label-two"><Icon name="flask" size={18}/><span>A new discovery</span></div><div className="orbit-label label-three"><span className="gold-spark">✦</span> Your kind of future</div><span className="orbit-star star-one">✦</span><span className="orbit-star star-two">✧</span></div></section>
    <div className="filter-bar"><label className="search-field"><Icon name="search" size={18}/><input aria-label="Search courses" placeholder="Search courses, topics, or course codes…" value={query} onChange={e=>setQuery(e.target.value)}/>{query&&<button type="button" className="icon-button" aria-label="Clear search" onClick={()=>setQuery("")}><Icon name="close" size={15}/></button>}</label><select aria-label="Assessment format" value={format} onChange={e=>setFormat(e.target.value)}><option>All formats</option><option value="Projects">Project-focused</option><option value="Exams">Exam-focused</option><option value="Mixed">Mixed assessment</option></select><select aria-label="Course level" value={level} onChange={e=>setLevel(e.target.value)}><option>All levels</option><option>Foundations</option><option>Advanced</option></select><button className={`btn saved-filter ${onlySaved?"selected":"secondary"}`} type="button" aria-pressed={onlySaved} onClick={()=>setOnlySaved(!onlySaved)}><Icon name="bookmark" size={16}/>Saved</button></div>
    {filtered.length>0?<>
      <section aria-labelledby="recommended-heading"><div className="section-heading"><div><div className="section-title"><span className="spark-tile"><Icon name="spark" size={17}/></span><h2 id="recommended-heading">A good place to start</h2><span className="count-pill">{top.length} picks</span></div><p>Personalized to your interests, study style, and weekly workload.</p></div><button className="text-button" onClick={()=>setShowMethod(!showMethod)} aria-expanded={showMethod}>{showMethod?"Hide details":"Why these courses?"}<Icon name="info" size={15}/></button></div>
      {showMethod&&<div className="method-note"><strong>Transparent demo matching</strong><p>Each shared interest adds 30 points, a preferred assessment format adds 18, and staying within your weekly workload adds 12. Missing sample prerequisites reduce the score by 12 each; workload above your preference reduces it by 3 per extra hour. Completed courses are excluded. These are relative rankings, not probabilities or eligibility decisions.</p><Link href="/profile">Update your profile <Icon name="arrow" size={14}/></Link></div>}
      {top.length?<div className="recommended-grid">{top.map((r,i)=><CourseCard key={r.course.id} course={r.course} index={i}/>)}</div>:<div className="inline-note">No new recommendations: the matching courses are already marked complete in your profile.</div>}
      </section>
      <section className="catalog-section" aria-labelledby="catalog-heading"><div className="section-heading"><div><div className="section-title"><h2 id="catalog-heading">Keep exploring</h2><span className="count-pill">{rest.length} courses</span></div><p>The rest of the catalog, alphabetically by course name.</p></div><span className="sort-label">Course name <span>A–Z ↓</span></span></div>
      {rest.length?<div className="catalog-table"><div className="table-head"><span>COURSE</span><span>FOCUS AREA</span><span>WEEKLY WORKLOAD</span><span>FORMAT</span><span className="sr-only">Save or view</span></div>{rest.map(course=><div className="course-row" key={course.id}><div className="table-course"><span className={`course-icon ${course.color}`}><Icon name={course.icon} size={21}/></span><div><span className="table-course-id">{course.id}{profile.completed.includes(course.id)&&<span className="completed-label"> · Completed</span>}</span><Link href={`/courses/${course.slug}`}>{course.title}</Link></div></div><span className="table-focus">{course.tags[0]}</span><span className="table-workload"><Icon name="clock" size={14}/>{course.hours} hrs / week</span><span><span className="format-pill">{course.format}</span></span><div className="row-actions"><SaveCourse course={course} compact/><Link className="icon-button" href={`/courses/${course.slug}`} aria-label={`View ${course.title}`}><Icon name="chevron" size={16}/></Link></div></div>)}</div>:<div className="inline-note">All matching courses are shown above.</div>}
      </section>
    </>:<div className="empty-state"><Icon name="search" size={34}/><h2>No courses found</h2><p>Try another topic or clear your filters to explore the sample catalog.</p><button className="btn primary" onClick={()=>{setQuery("");setFormat("All formats");setLevel("All levels");setOnlySaved(false);}}>Clear filters</button></div>}
    {isFiltering&&filtered.length>0&&<p className="results-note">Showing {filtered.length} of {courses.length} sample courses. <button className="text-button" onClick={()=>{setQuery("");setFormat("All formats");setLevel("All levels");setOnlySaved(false);}}>Reset filters</button></p>}
    <section className="bottom-callout"><span className="callout-icon"><Icon name="flask" size={25}/></span><div><h3>Your curiosity doesn’t stop at the classroom.</h3><p>See how your interests connect to research directions worth exploring.</p></div><Link className="text-button" href="/research">Discover research <Icon name="arrow" size={17}/></Link></section>
  </div>;
}
